                teamNataliaRegion: "АЛЬТМАРККРАЙС ЗАЛЬЦВЕДЕЛЬ", teamAnnelieRegion: "БЁРДЕ И МАГДЕБУРГ", teamMathiasRegion: "ЙЕРИХОВЕР-ЛАНД И МАГДЕБУРГ", teamSaschaRegion: "БЁРДЕ",
